suppressPackageStartupMessages(library(survival))
value <- (function() {
  a <- as.character(Surv2(c(1, 2.5, 10, NA), c(1, 0, 1, 1)))
  b <- as.character(Surv2(
    c(70, 72, 75, 78),
    factor(c("CU", "CU", "MCI", "dementia"), levels = c("CU", "MCI", "dementia"))
  ))
  c(paste(a, collapse = " "), paste(b, collapse = " "))
})()
cat(paste(value, collapse = "\n"), "\n", sep = "")
